from collections import deque
def bfs_path(gi, srcs, dst):
    # multi-source BFS over cells with value 0 or 1
    dist={}
    q=deque()
    for s in srcs: dist[s]=0; q.append(s)
    while q:
        r,c=q.popleft()
        if (r,c)==dst: break
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<7 and 0<=cc<7 and gi[rr][cc] in (0,1) and (rr,cc) not in dist:
                dist[(rr,cc)]=dist[(r,c)]+1; q.append((rr,cc))
    # reconstruct
    if dst not in dist: return None
    path=[dst]; cur=dst
    while cur not in srcs:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=cur[0]+dr,cur[1]+dc
            if 0<=rr<7 and 0<=cc<7 and (rr,cc) in dist and dist[(rr,cc)]==dist[cur]-1:
                cur=(rr,cc); path.append(cur); break
    return path[::-1]
