def components(gi):
    seen=set(); comps=[]
    for r in range(7):
        for c in range(7):
            if gi[r][c] in (0,1) and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    x=q.pop(); comp.append(x)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=x[0]+dr,x[1]+dc
                        if 0<=rr<7 and 0<=cc<7 and gi[rr][cc] in (0,1) and (rr,cc) not in seen:
                            seen.add((rr,cc)); q.append((rr,cc))
                comps.append(comp)
    return comps
def norm(cells):
